import java.util.Scanner;

public class Main {
    static final int MAXN = 1000005;
    static boolean[] vis = new boolean[MAXN];
    static final long MOD = 1000000007;

    public static long fastPow(long a, int b) {
        long res = 1;
        while (b > 0) {
            if ((b & 1) == 1) {
                res = res * a % MOD;
            }
            b >>= 1;
            a = a * a % MOD;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        if (k == 0) {
            System.out.println(fastPow(p, (int) p - 1));
            return;
        }
        if (k == 1) {
            System.out.println(fastPow(p, (int) p));
            return;
        }

        int cnt = 0;
        for (int i = 1; i < p; i++) {
            if (vis[i]) continue;
            long j = i;
            while (!vis[(int) j]) {
                vis[(int) j] = true;
                j = (j * k) % p;
            }
            cnt++;
        }
        System.out.println(fastPow(p, cnt));
    }
}
